* {
    padding: 0;
    margin: 0;
    box-sizing: border-box;
}

body {
    background-color: #ff9e80;
}

.calculator {
    display: block;
    width: 995px;
    height: 476px;
    margin: calc(50vh - 150px) auto 0 auto;
    background-color: #333;
    background-image: linear-gradient(90deg, #e6ebee, #f0f0f0);
    box-shadow: 0px 0px 0px 0px #b1b8c0 inset, 0px -10px 10px 10px #b1b8c0 inset,
        0px 1px 0px 2px #b1b8c0 inset, 0 55px 10px -25px rgba(0, 0, 0, 0.1),
        0 65px 30px -10px rgba(0, 0, 0, 0.5);
    z-index: 1;
    border-radius: 10px;
}

.out {
    display: block;
    background-color: transparent;
    margin: -6px auto auto 10px;
    border-radius: 5px;
    width: 965px;
    height: 490px;
    position: absolute;
    z-index: -1;
}

.lcdBorder {
    display: block;
    z-index: 1;
    background-color: #222816;
    width: 760px;
    height: 105px;
    position: absolute;
    margin: 30px auto auto 30px;
    border-radius: 3px;
    box-shadow: 0 5px 20px 0.05px #130f0a inset, 5px 0 10px -4px #130f0a inset,
        -0.5px 0 3px 1px #130f0a inset, 0 0 0 2px rgba(0, 0, 0, 1),
        0 65px 50px -10px rgba(0, 0, 0, -0.05);
}

.lcd {
    display: block;
    z-index: 2;
    background-color: #99a883;
    width: 700px;
    height: 60px;
    position: absolute;
    margin: 50px auto auto 60px;
    border-radius: 3px;
    box-shadow: 0 5px 20px 0.05px #130f0a inset, 5px 0 10px -4px #130f0a inset,
        -0.5px 0 3px 1px #130f0a inset, 0 0 0 2px rgba(0, 0, 0, 1),
        0 65px 50px -10px rgba(0, 0, 0, -0.05);
}

.lcd p:nth-child(1) {
    display: inline-block;
    font-family: "Orbitron", sans-serif;
    opacity: 0.5;
    margin: auto auto auto 150px;
    font-size: 0.6em;
}

.lcd p:nth-child(2) {
    display: inline-block;
    font-family: "Orbitron", sans-serif;
